"""Stile del workbench, senza asset o dipendenze esterne."""
STYLE = """
:root{--paper:#f7f5ef;--ink:#242b2c;--green:#205c53;--muted:#435754;--line:#bac5bd;--warn:#74430b;--focus:#b46100}
*{box-sizing:border-box}body{font:16px/1.55 system-ui,sans-serif;background:var(--paper);color:var(--ink);margin:0}
header{display:flex;align-items:center;gap:24px;padding:18px 32px;border-bottom:1px solid var(--line)}header strong{letter-spacing:.17em;font-size:22px}header span{font-size:12px;letter-spacing:.08em}.badge{margin-left:auto;background:#e0ebe4;padding:6px 12px;border-radius:3px}
.shell{display:grid;grid-template-columns:280px minmax(0,1fr);min-height:calc(100vh - 80px)}aside{padding:28px 24px;border-right:1px solid var(--line);background:#eeeee5}main{padding:28px 36px;min-width:0;max-width:1600px;width:100%}
h1,h2,h3{line-height:1.25;margin:0 0 16px}h1{font-size:22px}h2{font-size:30px}h3{font-size:19px}p{margin:12px 0}label{display:block;font-size:14px;font-weight:650;margin-bottom:6px}
input,select,button,summary{font:inherit;min-height:44px}input,select{width:100%;min-width:0;border:1px solid #73827a;border-radius:4px;padding:9px;background:#fff;color:var(--ink)}button{border:1px solid var(--green);background:var(--green);color:#fff;border-radius:4px;padding:9px 16px;cursor:pointer}button:disabled{opacity:.55;cursor:default}button[aria-pressed=false]{background:transparent;color:var(--green)}button:hover:not(:disabled){filter:brightness(.93)}
:focus-visible{outline:3px solid var(--focus);outline-offset:3px}main:focus,#detail:focus{outline-offset:-3px}.skip{position:absolute;left:12px;top:-90px;background:white;color:var(--green);padding:10px;z-index:2}.skip:focus{top:8px}
details{border-top:1px solid var(--line);margin-top:22px;padding-top:10px}summary{cursor:pointer;padding:8px 0}form button{margin-top:12px}aside input{font-size:14px}aside .hint{margin-top:30px}#message{overflow-wrap:anywhere}.hint{color:var(--muted);font-size:14px}.hint,.path,code,pre,li,dd{overflow-wrap:anywhere}.path{font-size:14px}.eyebrow{color:var(--muted);font-size:12px;letter-spacing:.1em;margin:0 0 5px}.heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.heading button{background:transparent;color:var(--green)}
nav{display:flex;gap:8px;border-bottom:1px solid var(--line);padding:12px 0;margin-bottom:20px;flex-wrap:wrap}.toolbar{display:grid;grid-template-columns:1fr 1fr 1.4fr auto;align-items:end;gap:12px}.toolbar button{margin:0}.columns{display:grid;grid-template-columns:minmax(180px,1fr) minmax(0,1.4fr);gap:28px;margin-top:24px}.columns>section{min-width:0}#detail{border-left:1px solid var(--line);padding-left:24px}.node-list{list-style:none;padding:0;margin:0;max-height:480px;overflow:auto}.node-list li{border-top:1px solid var(--line)}.node-list button{display:block;text-align:left;width:100%;background:transparent;border:0;color:var(--green);border-radius:0;padding:12px 8px}.node-list small{display:block;color:var(--muted)}#notice:not(:empty){background:#fff0d6;border-left:4px solid var(--warn);padding:12px;color:#563208}#more{margin:12px 0}pre{font:14px/1.6 ui-monospace,monospace;white-space:pre-wrap;background:#eeeee5;padding:16px;max-height:520px;overflow:auto}dt{font-weight:650}dd{margin:0 0 12px}code{font-size:13px}ul{padding-left:22px}#map{overflow-x:auto}#map svg{min-width:700px;display:block;width:100%;height:auto;max-height:350px;border:1px solid var(--line);background:#fffdf7}#map text{font:13px system-ui;fill:var(--ink)}#map .dot{cursor:pointer;fill:#dce9e0;stroke:var(--green);stroke-width:2}#map [role=button]:focus .dot{stroke:var(--focus);stroke-width:4}#ontology article{border-top:1px solid var(--line);padding:16px 0}[hidden]{display:none!important}
@media(max-width:1000px){.toolbar{grid-template-columns:1fr 1fr}.shell{grid-template-columns:235px minmax(0,1fr)}main{padding:24px}.columns{grid-template-columns:1fr}#detail{border-left:0;border-top:1px solid var(--line);padding:20px 0 0}}
@media(max-width:640px){header{padding:14px 18px;gap:12px}header span:not(.badge){display:none}.shell{display:block}aside{padding:20px;border-right:0;border-bottom:1px solid var(--line)}aside .hint{margin-top:16px}main{padding:24px 20px}.heading{align-items:flex-start}h2{font-size:26px}.toolbar{grid-template-columns:1fr}nav button{flex:1;padding:9px}#map svg{min-height:230px}.node-list{max-height:320px}}
"""
